// Parse and classify support request
const email = $input.first().json;
const subject = (email.subject || '').toLowerCase();
const body = (email.textPlain || email.body || '').toLowerCase();
const fullText = `${subject} ${body}`;
const from = email.from || '';

// Extract sender info
const emailMatch = from.match(/<?([^\s<>,]+@[^\s<>,]+)>?/);
const senderEmail = emailMatch ? emailMatch[1] : '';
const nameMatch = from.match(/([A-ZÀ-Ỹ][a-zà-ỹ]+(?:\s[A-ZÀ-Ỹ][a-zà-ỹ]+)+)/);
const senderName = nameMatch ? nameMatch[1] : senderEmail.split('@')[0];

// Classification keywords (Vietnamese + English)
const categories = {
  refund: {
    keywords: ['hoàn tiền', 'refund', 'trả lại', 'return money', 'hoàn trả', 'xin tiền lại', 'không nhận được hàng'],
    priority: 'high',
    sla_hours: 4
  },
  product_question: {
    keywords: ['hỏi', 'question', 'tư vấn', 'thông tin', 'info', 'giới thiệu', 'tính năng', 'feature', 'giá', 'price', 'chi phí'],
    priority: 'medium',
    sla_hours: 8
  },
  technical_issue: {
    keywords: ['lỗi', 'error', 'bug', 'không hoạt động', 'bị hỏng', 'không dùng được', 'crash', 'freeze', 'chậm', 'slow', 'không đăng nhập', 'login'],
    priority: 'urgent',
    sla_hours: 2
  },
  complaint: {
    keywords: ['khiếu nại', 'complaint', 'phàn nàn', 'tệ', 'bad', 'terrible', 'worst', 'thất vọng', 'disappointed', 'dịch vụ kém'],
    priority: 'urgent',
    sla_hours: 2
  }
};

let requestType = 'general';
let priority = 'low';
let slaHours = 24;

for (const [type, config] of Object.entries(categories)) {
  const keywordCount = config.keywords.filter(kw => fullText.includes(kw)).length;
  if (keywordCount > 0) {
    requestType = type;
    priority = config.priority;
    slaHours = config.sla_hours;
    break;
  }
}

// Generate ticket ID
const ticketId = `TKT-${Date.now().toString().slice(-8)}`;
const now = new Date();
const slaDeadline = new Date(now.getTime() + slaHours * 60 * 60 * 1000);

// Extract amount for refund requests
let refundAmount = null;
if (requestType === 'refund') {
  const amountMatch = fullText.match(/([\d\.,]+)\s*(?:[Vv][Nn][Dd]|[₫đ])/);
  if (amountMatch) {
    refundAmount = parseFloat(amountMatch[1].replace(/[\.,]/g, ''));
  }
}

return [{
  json: {
    ticket_id: ticketId,
    sender_name: senderName,
    sender_email: senderEmail,
    subject: email.subject,
    body: email.textPlain || email.body,
    request_type: requestType,
    request_type_vn: {
      refund: 'Yêu cầu hoàn tiền',
      product_question: 'Hỏi về sản phẩm',
      technical_issue: 'Lỗi kỹ thuật',
      complaint: 'Khiếu nại',
      general: 'Yêu cầu chung'
    }[requestType],
    priority,
    priority_vn: {
      urgent: 'Khẩn',
      high: 'Cao',
      medium: 'Trung bình',
      low: 'Thấp'
    }[priority],
    sla_hours: slaHours,
    sla_deadline: slaDeadline.toISOString(),
    created_at: now.toISOString(),
    timezone: 'Asia/Ho_Chi_Minh',
    refund_amount: refundAmount,
    refund_amount_formatted: refundAmount ? `${refundAmount.toLocaleString('vi-VN')}đ` : null,
    auto_approve_refund: refundAmount ? refundAmount < 500000 : false,
    status: 'new'
  }
}];

